import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.BkO3HzvX.js";const c=JSON.parse('{"title":"安装与平台","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/installation-platforms.md","filePath":"zh/guides/installation-platforms.md"}'),n={name:"zh/guides/installation-platforms.md"};function p(l,a,h,d,o,k){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="安装与平台" tabindex="-1">安装与平台 <a class="header-anchor" href="#安装与平台" aria-label="Permalink to &quot;安装与平台&quot;">​</a></h1><p>Neony 会把 Python 构建的 DOM 树渲染到原生 WebView 中。安装 Python 包只是 必要条件之一；WebView 和部分可选桌面集成由操作系统提供。</p><h2 id="python-环境" tabindex="-1">Python 环境 <a class="header-anchor" href="#python-环境" aria-label="Permalink to &quot;Python 环境&quot;">​</a></h2><p>从包索引安装应用依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neony</span></span></code></pre></div><p>要构建或修改仓库本身，请使用<a href="https://github.com/HarcicYang/Neony/blob/c3f9724/CONTRIBUTING.zh.md" target="_blank" rel="noreferrer">贡献指南</a>中记录的 开发环境。</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>项目主要在 Linux Wayland 上开发和验证。原生 WebView 绑定链接的是 <strong>WebKitGTK 4.1</strong> API（GTK 3、libsoup 3），因此每个发行版都需要安装能提供 <code>libwebkit2gtk-4.1.so.0</code> 的包。不同发行版的包名不同，下面给出常见发行版 的安装命令。</p><h3 id="开发依赖" tabindex="-1">开发依赖 <a class="header-anchor" href="#开发依赖" aria-label="Permalink to &quot;开发依赖&quot;">​</a></h3><p>Debian 和 Ubuntu：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libwebkit2gtk-4.1-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libgtk-3-dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-dev</span></span></code></pre></div><p>Fedora：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webkit2gtk4.1-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-devel</span></span></code></pre></div><p>Arch Linux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --needed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webkit2gtk-4.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xdotool</span></span></code></pre></div><p>openSUSE：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zypper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libwebkit2gtk-4_1-0-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gtk3-devel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libxdo-devel</span></span></code></pre></div><blockquote><p>上面的每个 <code>-dev</code>/<code>-devel</code>/普通包都会通过依赖关系自动带入与之匹配的 WebKitGTK 4.1 运行时、GTK 3 和 libsoup 3。</p></blockquote><h3 id="打包应用所需的运行时依赖" tabindex="-1">打包应用所需的运行时依赖 <a class="header-anchor" href="#打包应用所需的运行时依赖" aria-label="Permalink to &quot;打包应用所需的运行时依赖&quot;">​</a></h3><p>打包后的应用需要对应的 WebKitGTK <strong>运行时</strong>，而不是编译头文件。在目标机器上 只需安装运行时包：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Debian/Ubuntu : sudo apt-get install libwebkit2gtk-4.1-0</span></span>
<span class="line"><span>Fedora        : sudo dnf install webkit2gtk4.1</span></span>
<span class="line"><span>Arch Linux    : sudo pacman -S webkit2gtk-4.1</span></span>
<span class="line"><span>openSUSE      : sudo zypper install libwebkit2gtk-4_1-0</span></span></code></pre></div><h3 id="可选的系统托盘依赖" tabindex="-1">可选的系统托盘依赖 <a class="header-anchor" href="#可选的系统托盘依赖" aria-label="Permalink to &quot;可选的系统托盘依赖&quot;">​</a></h3><p>原生托盘集成在运行时动态加载该库，因此它是可选依赖而非硬链接：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Debian/Ubuntu : libayatana-appindicator3-1  （构建时还需 libayatana-appindicator3-dev）</span></span>
<span class="line"><span>Fedora        : libayatana-appindicator-gtk3</span></span>
<span class="line"><span>Arch Linux    : libayatana-appindicator</span></span>
<span class="line"><span>openSUSE      : libayatana-appindicator3-1</span></span></code></pre></div><p>如果它不存在，普通窗口应用仍可运行；应用层会记录日志并跳过托盘创建。</p><h3 id="wayland-与-x11" tabindex="-1">Wayland 与 X11 <a class="header-anchor" href="#wayland-与-x11" aria-label="Permalink to &quot;Wayland 与 X11&quot;">​</a></h3><p>Wayland 是当前 Linux 的主要桌面目标。Linux blur 会在支持的 compositor 上 使用 background-effect 协议；窗口定位也会受到 Wayland 规则限制。X11 目前 不是完整支持目标。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Windows 使用系统 WebView2 runtime。运行应用前请安装或启用 WebView2。Acrylic、 Mica 等原生窗口材质取决于平台和窗口配置。</p><p>正式发布前仍应在目标 Windows 版本上单独验证所需功能。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>macOS 使用系统提供的 WKWebView。文件对话框使用 <code>osascript</code>，透明窗口可以请求 原生 blur。WKWebView 不会在 web drop 事件中提供完整的文件系统元数据；依赖文件 路径的应用应使用 Neony native drop channel，并在目标系统上测试。</p><p>macOS runtime 和 HiDPI/mixed-DPI 行为属于需要单独验证的平台工作。</p><h2 id="hevc-编解码回退" tabindex="-1">HEVC / 编解码回退 <a class="header-anchor" href="#hevc-编解码回退" aria-label="Permalink to &quot;HEVC / 编解码回退&quot;">​</a></h2><p>WebView 媒体管线不保证支持 HEVC（<code>hvc1</code> / <code>hev1</code>）。受管 <code>Video</code> / <code>Audio</code> 加载本地 MP4 且运行时无法解码时，会检测编码并借助 <code>imageio-ffmpeg</code> 透明转码为 H.264。该 wheel 自带静态 ffmpeg，因此不需要 安装系统 <code>ffmpeg</code> 或媒体工具链。转码结果缓存在原文件旁 <code>&lt;file&gt;.transcoded.mp4</code>，后续启动直接复用。</p><h2 id="原生文件对话框" tabindex="-1">原生文件对话框 <a class="header-anchor" href="#原生文件对话框" aria-label="Permalink to &quot;原生文件对话框&quot;">​</a></h2><p>公开的异步方法是：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.open_file()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">paths </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.open_files()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">destination </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.save_file(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">default_name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;output.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">folder </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.select_folder()</span></span></code></pre></div><p>平台实现会自动选择：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Linux   → 优先 zenity，否则 tkinter</span></span>
<span class="line"><span>macOS   → osascript</span></span>
<span class="line"><span>Windows → PowerShell</span></span>
<span class="line"><span>其他    → tkinter fallback</span></span></code></pre></div><p>选择器异步打开，对话框开启期间应用仍可响应其他任务。</p><p>单选取消返回 <code>None</code>，多选取消返回 <code>[]</code>。文件过滤器使用 <code>(label, pattern)</code> 列表，例如：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filetypes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PNG images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.png&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;All files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span></code></pre></div><p>平台命令或 fallback 无法启动时，公开 API 会把常见失败/取消结果归一为同样的空 返回形状。正式发布到某个平台前，应在该平台实测 picker 行为。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>首要检查</th></tr></thead><tbody><tr><td>Linux WebView 无法启动</td><td>确认 WebKitGTK runtime 和 GTK 库已安装，查看进程 stderr。</td></tr><tr><td>没有托盘图标</td><td>安装 <code>libayatana-appindicator</code>；托盘是可选功能，创建失败会被跳过。</td></tr><tr><td>文件选择器没有出现</td><td>检查 <code>zenity</code>/<code>osascript</code>/PowerShell 或 tkinter，以及显示会话环境。</td></tr><tr><td>透明窗口没有 blur</td><td>检查 compositor/平台支持；blur 失败不会让窗口崩溃，窗口仍可使用。</td></tr></tbody></table><p>想先运行一个应用，请回到<a href="/neony/zh/getting-started.html">入门教程</a>。需要精确配置 字段时，请查阅 <a href="/neony/zh/api/">API 索引</a>。</p>`,47)])])}const g=s(n,[["render",p]]);export{c as __pageData,g as default};
